108	// DeleteMemoShare revokes a share link.
109	// Only the memo's creator or an admin may call this.
110	func (s *APIV1Service) DeleteMemoShare(ctx context.Context, request *v1pb.DeleteMemoShareRequest) (*emptypb.Empty, error) {
111		user, err := s.fetchCurrentUser(ctx)
112		if err != nil {
113			return nil, status.Errorf(codes.Internal, "failed to get user")
114		}
115		if user == nil {
116			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
117		}
118	
119		// name format: memos/{memoUID}/shares/{shareToken}
120		tokens, err := GetNameParentTokens(request.Name, MemoNamePrefix, MemoShareNamePrefix)
121		if err != nil {
122			return nil, status.Errorf(codes.InvalidArgument, "invalid share name: %v", err)
123		}
124		memoUID, shareToken := tokens[0], tokens[1]
125	
126		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
127		if err != nil {
128			return nil, status.Errorf(codes.Internal, "failed to get memo")
129		}
130		if memo == nil {
131			return nil, status.Errorf(codes.NotFound, "memo not found")
132		}
133		if memo.CreatorID != user.ID && !isSuperUser(user) {
134			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
135		}
136	
137		ms, err := s.Store.GetMemoShare(ctx, &store.FindMemoShare{UID: &shareToken})
138		if err != nil {
139			return nil, status.Errorf(codes.Internal, "failed to get memo share")
140		}
141		if ms == nil || ms.MemoID != memo.ID {
142			return nil, status.Errorf(codes.NotFound, "memo share not found")
143		}
144	
145		if err := s.Store.DeleteMemoShare(ctx, &store.DeleteMemoShare{UID: &shareToken}); err != nil {
146			return nil, status.Errorf(codes.Internal, "failed to delete memo share")
147		}
148		return &emptypb.Empty{}, nil
149	}
