195	func (d *DB) UpdateMemo(ctx context.Context, update *store.UpdateMemo) error {
196		set, args := []string{}, []any{}
197		if v := update.UID; v != nil {
198			set, args = append(set, "`uid` = ?"), append(args, *v)
199		}
200		if v := update.CreatedTs; v != nil {
201			set, args = append(set, "`created_ts` = ?"), append(args, *v)
202		}
203		if v := update.UpdatedTs; v != nil {
204			set, args = append(set, "`updated_ts` = ?"), append(args, *v)
205		}
206		if v := update.RowStatus; v != nil {
207			set, args = append(set, "`row_status` = ?"), append(args, *v)
208		}
209		if v := update.Content; v != nil {
210			set, args = append(set, "`content` = ?"), append(args, *v)
211		}
212		if v := update.Visibility; v != nil {
213			set, args = append(set, "`visibility` = ?"), append(args, *v)
214		}
215		if v := update.Pinned; v != nil {
216			set, args = append(set, "`pinned` = ?"), append(args, *v)
217		}
218		if v := update.Payload; v != nil {
219			payloadBytes, err := protojson.Marshal(v)
220			if err != nil {
221				return err
222			}
223			set, args = append(set, "`payload` = ?"), append(args, string(payloadBytes))
224		}
225		if len(set) == 0 {
226			return nil
227		}
228		args = append(args, update.ID)
229	
230		stmt := "UPDATE `memo` SET " + strings.Join(set, ", ") + " WHERE `id` = ?"
231		if _, err := d.db.ExecContext(ctx, stmt, args...); err != nil {
232			return err
233		}
234		return nil
235	}
